fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    // All input vectors must have the same length
    let n = vals_1.len();
    debug_assert_eq!(vals_2.len(), n, "vals_2 must have length {}", n);
    debug_assert_eq!(conds_1.len(), n, "conds_1 must have length {}", n);
    debug_assert_eq!(conds_2.len(), n, "conds_2 must have length {}", n);

    // Overwrite any previous contents of `avgs`
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let take1 = conds_1[i];
        let take2 = conds_2[i];

        // By assumption, at least one of take1 or take2 is true
        let out = if take1 && take2 {
            // both true: average the two values
            (vals_1[i] + vals_2[i]) / 2
        } else if take1 {
            // only the first condition is true
            vals_1[i]
        } else {
            // only the second condition is true
            vals_2[i]
        };

        avgs.push(out);
    }
}